[],"residual":"","coberturas":[{"legacy_id":597,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Contrato fuente íntegro en descripción de S22AD-C08; conserva semántica y referencias literales, sin habilitar runtime."}],"hechos":["s22ad08_evalua_campana","s22ad08_reescribe_oferta_base","s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado","s22ad08_acumula_descuentos_sin_politica","s22ad08_precio_cambia_antes_vigencia","s22ad08_bono_retirado_o_sustituye_devolucion","s22ad08_persistencia_inventada"],"paquete":{"tipo":"NUEVA","codigo":"S22AD-C08","clave":"s22ad_legacy_597","familia":"B2B_PARTNERS","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"B2B","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Campaña B2B gobernada sin sobrescribir oferta","descripcion":"BLOQUEAR incumplimiento del contrato funcional REG_LF_BENEFITS_B2B_CAMPAIGN_001. Un aliado B2B puede definir campañas comerciales temporales —por ejemplo Cyber/WOW, aniversario u otra campaña especial— que mejoren las condiciones de una oferta elegible. La campaña no sustituye ni reescribe silenciosamente la oferta base: aplica un ajuste comercial gobernado, con vigencia y alcance explícitos. Debe poder definirse quién financia el beneficio, a qué cartera/ofertas o segmentos aplica, su período de vigencia, topes y la política de combinación con otros descuentos o beneficios de membresía. No se asume suma automática entre descuentos: la combinación debe resolverse desde configuración autorizada. Si el beneficio de aviso anticipado de membresía está activo, una campaña B2B futura puede comunicarse anticipadamente a miembros elegibles sin modificar todavía el precio hasta que la campaña entre en vigencia. Bono y cupón se consideran instrumentos comerciales no retirables y no equivalentes a dinero; no crean wallet y nunca sustituyen una devolución. Su aplicación al precio debe resolverse por configuración/pricing autorizado. Referencias literales del contrato fuente (no nuevas configuraciones ni autorización de implementación): {\"decision_adr\":\"ADR-LF-BEN-001\",\"withdrawable\":false,\"cash_equivalent\":false,\"wallet_required\":false,\"applicability_v1\":{\"all\":[],\"any\":[{\"op\":\"IN\",\"path\":[\"target\",\"screen\",\"id\"],\"values\":[5]}],\"status\":\"ACTIVE\",\"provenance\":{\"authority\":\"OWNER_AUTHORIZED_GOVERNED_MIGRATION\",\"r14_event_id\":19951,\"migration_source\":\"LEGACY_POSITIVE_BINDINGS_FOR_EQUIVALENCE_ONLY\",\"decision_event_id\":19948,\"migration_version\":\"20261002173000\"},\"consumer_roles\":[\"INPUT_GOVERNANCE\"],\"schema_version\":\"lf-rule-applicability/v1\"},\"pricing_registry\":\"public.lf_b2b_pricing_config\",\"application_order\":\"VERSIONED_PRICING_CONFIG\",\"application_scope\":\"CONFIG_DRIVEN_PRICING_COMPONENT_OR_ELIGIBLE_DEBT\",\"caps_configurable\":true,\"refund_substitute\":\"DENY\",\"validity_required\":true,\"scope_configurable\":true,\"redemption_mechanism\":\"PENDING_CANONICAL_PRODUCT_MODEL\",\"audience_configurable\":true,\"screen_bindings_status\":\"PENDING_SCREEN_BY_SCREEN_REVIEW\",\"campaign_name_hardcoded\":\"DENY\",\"client_instrument_types\":[\"DISCOUNT\",\"BONUS\",\"COUPON\"],\"existing_authority_rule\":\"REG_B2B_001\",\"goodwill_incident_bonus\":\"ALLOW_AS_SEPARATE_BENEFIT\",\"stacking_policy_required\":true,\"automatic_discount_stacking\":\"DENY\",\"base_offer_silent_overwrite\":\"DENY\",\"discount_value_configurable\":true,\"funding_source_configurable\":true,\"member_early_alert_optional\":true,\"pricing_quote_snapshot_path\":\"selection_snapshot.applied_commercial_adjustments\",\"specific_persistence_status\":\"PENDING_CANONICAL_PRODUCT_MODULE_AND_CAMPAIGN_MODEL\",\"campaign_override_capability\":\"campaign_override_allowed\",\"campaign_enabled_configurable\":true}. Los estados pendientes y restricciones de producción se conservan; binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/597","solicitante":"Cristhian / Claude S22-AD 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22ad08_evalua_campana"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22ad08_reescribe_oferta_base"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ad08_acumula_descuentos_sin_politica"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ad08_precio_cambia_antes_vigencia"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ad08_bono_retirado_o_sustituye_devolucion"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ad08_persistencia_inventada"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22ad08_evalua_campana":true,"s22ad08_reescribe_oferta_base":false,"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado":false,"s22ad08_acumula_descuentos_sin_politica":false,"s22ad08_precio_cambia_antes_vigencia":false,"s22ad08_bono_retirado_o_sustituye_devolucion":false,"s22ad08_persistencia_inventada":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22ad08_evalua_campana":true,"s22ad08_reescribe_oferta_base":true,"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado":false,"s22ad08_acumula_descuentos_sin_politica":false,"s22ad08_precio_cambia_antes_vigencia":false,"s22ad08_bono_retirado_o_sustituye_devolucion":false,"s22ad08_persistencia_inventada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ad08_evalua_campana":true,"s22ad08_reescribe_oferta_base":false,"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado":true,"s22ad08_acumula_descuentos_sin_politica":false,"s22ad08_precio_cambia_antes_vigencia":false,"s22ad08_bono_retirado_o_sustituye_devolucion":false,"s22ad08_persistencia_inventada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ad08_evalua_campana":true,"s22ad08_reescribe_oferta_base":false,"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado":false,"s22ad08_acumula_descuentos_sin_politica":true,"s22ad08_precio_cambia_antes_vigencia":false,"s22ad08_bono_retirado_o_sustituye_devolucion":false,"s22ad08_persistencia_inventada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ad08_evalua_campana":true,"s22ad08_reescribe_oferta_base":false,"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado":false,"s22ad08_acumula_descuentos_sin_politica":false,"s22ad08_precio_cambia_antes_vigencia":true,"s22ad08_bono_retirado_o_sustituye_devolucion":false,"s22ad08_persistencia_inventada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ad08_evalua_campana":true,"s22ad08_reescribe_oferta_base":false,"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado":false,"s22ad08_acumula_descuentos_sin_politica":false,"s22ad08_precio_cambia_antes_vigencia":false,"s22ad08_bono_retirado_o_sustituye_devolucion":true,"s22ad08_persistencia_inventada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ad08_evalua_campana":true,"s22ad08_reescribe_oferta_base":false,"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado":false,"s22ad08_acumula_descuentos_sin_politica":false,"s22ad08_precio_cambia_antes_vigencia":false,"s22ad08_bono_retirado_o_sustituye_devolucion":false,"s22ad08_persistencia_inventada":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22ad08_evalua_campana":false,"s22ad08_reescribe_oferta_base":true,"s22ad08_vigencia_alcance_fondeo_o_tope_no_gobernado":true,"s22ad08_acumula_descuentos_sin_politica":true,"s22ad08_precio_cambia_antes_vigencia":true,"s22ad08_bono_retirado_o_sustituye_devolucion":true,"s22ad08_persistencia_inventada":true},"esperado":false}]},"hash":"1e6d2395e1077af6f768456e72a8992891699e6b124c4bb072ce320f305e62ce","hash_paquete":"5e1889a19bfc3f8cedfbdffa68df9b90c042c179a5064fb3170eeccc7d5ff7bb","hash_evaluado":"1e6d2395e1","hash_paquete_10":"5e1889a19b"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22AD proposal-only: independent judgment pending';
END $s22$;
COMMIT;
